module TopModule (
    input  logic       in,
    input  logic [1:0] state,
    output logic [1:0] next_state,
    output logic       out
);

    always_comb begin
        case (state)
            2'b00: begin
                next_state = in ? 2'b01 : 2'b00;
                out = 1'b0;
            end
            2'b01: begin
                next_state = in ? 2'b01 : 2'b10;
                out = 1'b0;
            end
            2'b10: begin
                next_state = in ? 2'b11 : 2'b00;
                out = 1'b0;
            end
            2'b11: begin
                next_state = in ? 2'b01 : 2'b10;
                out = 1'b1;
            end
            default: begin
                next_state = 2'b00;
                out = 1'b0;
            end
        endcase
    end

endmodule

